function validEntry(e) {
  const needed = ["name", "meaning", "type", "validValues"];
  const missing = needed.filter(k => !(k in e));
  return missing.length === 0 ? "VALID" : "Missing: " + missing.join(", ");
}
const entry = {
  name: "status",
  meaning: "the task's current state",
  type: "text",
  validValues: ["open", "in-progress", "completed"]
};
console.log(validEntry(entry));

